<?php
function accountSelect(string $name,string $label,array $accounts,bool $required=false,?int $selected=null): void { ?><label><?=e($label)?><select name="<?=e($name)?>" <?=$required?'required':''?>><option value=""><?=$required?'Choisir un compte':'Non affecté'?></option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=$selected===(int)$a['id']?'selected':''?>><?=e($a['name'].' · '.$a['kind'])?></option><?php endforeach?></select></label><?php }
$snapshot=financeSnapshot();$accounts=$snapshot['accounts'];
if($page==='finance'):
heading('TRÉSORERIE','La caisse et la banque, en clair.','Soldes calculés à partir des ouvertures, règlements confirmés, charges payées et transferts enregistrés.');
?><div class="document-actions"><a class="btn primary" href="<?=e(url('expenses'))?>">Gérer les charges</a><form method="post"><?=csrf()?><input type="hidden" name="action" value="finance_export"><button class="btn secondary">↓ Journal CSV complet</button></form></div><section class="panel padded"><h2>Comptes & soldes actuels</h2><?php if(!$accounts):?><p>Ajoutez votre caisse et vos comptes bancaires avec une date de départ et un solde initial vérifié.</p><?php else:?><div class="table-scroll"><table><thead><tr><th>COMPTE</th><th>OUVERTURE</th><th class="numeric">SOLDE INITIAL</th><th class="numeric">SOLDE ACTUEL</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><?=e($a['name'])?><small class="subline"><?=e($a['kind'])?></small></td><td><?=e($a['opening_date'])?></td><td class="numeric"><?=e(money($a['opening_balance']))?></td><td class="numeric amount"><?=e(signedMoney($snapshot['balances'][$a['id']]))?></td></tr><?php endforeach?></tbody></table></div><?php endif?><p class="small muted">Les comptes et leur ouverture sont conservés. Choisissez un solde initial avant les mouvements que vous allez suivre, pour ne pas les inclure deux fois.</p><details><summary>Ajouter un compte</summary><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="finance_account_add"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-grid"><?php inputField('Nom du compte','name','','text',true,'maxlength="120"');selectField('Type','kind',['Caisse','Banque'],'Caisse');inputField('Date de début du suivi','opening_date',date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"');inputField('Solde initial · DH, négatif possible','opening_balance','0.00','number',true,'min="-9999999999.99" max="9999999999.99" step="0.01"');?></div><button class="btn primary">Créer le compte</button></form></details></section>
<?php if($accounts):?><section class="panel padded commerce-block"><h2>Transfert interne déjà effectué</h2><p class="small muted">Exemple : dépôt d’espèces en banque. Une sortie et une entrée du même montant ; aucun ordre envoyé à une banque.</p><form method="post" data-confirm="Enregistrer ce transfert déjà effectué entre les deux comptes ?"><?=csrf()?><input type="hidden" name="action" value="finance_transfer"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-grid"><?php accountSelect('from_account_id','Compte débité',$accounts,true);accountSelect('to_account_id','Compte crédité',$accounts,true);inputField('Date effective','transfer_date',date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"');inputField('Montant · DH','amount','','number',true,'min="0.01" max="999999999.99" step="0.01"');inputField('Référence / motif','reference','','text',true,'maxlength="190"');?></div><div class="form-footer"><button class="btn secondary">Enregistrer le transfert</button></div></form></section><?php endif?>
<?php $unassigned=all("SELECT * FROM order_payments WHERE state='Confirmé' AND account_id IS NULL ORDER BY id DESC LIMIT 50");?><section class="panel padded commerce-block"><h2>Encaissements non affectés · <?=e(money(decimalString($snapshot['unassigned'],2)))?></h2><p class="small muted">Déjà comptés comme paiements clients, sans compte renseigné. L’affectation ne crée pas un second encaissement. Date historique affichée dans le fuseau configuré ; vérifiez la date effective de trésorerie.</p><?php foreach($unassigned as $p):?><form method="post" class="payment-form"><?=csrf()?><input type="hidden" name="action" value="payment_account"><input type="hidden" name="payment_id" value="<?=(int)$p['id']?>"><p><a href="<?=e(url('order_form',['id'=>$p['order_id']]))?>"><?=e(ref((int)$p['order_id']))?></a> · REG-<?=(int)$p['id']?> · <?=e(money($p['amount']))?> · <?=e($p['method'])?></p><div class="form-grid three"><?php accountSelect('account_id','Affecter au compte',$accounts,true);inputField('Date effective','financial_date',paymentFinanceDate($p),'date',true,'max="'.date('Y-m-d').'"');?><div class="field-action"><button class="btn secondary">Affecter ce règlement</button></div></div></form><?php endforeach?><?php if(count($unassigned)===50):?><p>50 plus récents ; affectez-les pour afficher les suivants.</p><?php endif?></section>
<?php $month=(string)($_GET['month']??date('Y-m'));try{payrollMonth($month);}catch(DomainException){$month=date('Y-m');}$accountFilter=max(0,(int)($_GET['account']??0));$entries=array_values(array_filter($snapshot['entries'],static fn($r)=>str_starts_with($r['date'],$month)&&(!$accountFilter||$r['account_id']===$accountFilter)));$receipts=0;$paidExpenses=0;foreach($entries as $r){if($r['source']==='Encaissement client')$receipts+=$r['signed'];if($r['source']==='Charge payée')$paidExpenses-=$r['signed'];}$count=count($entries);$p=max(1,min(max(1,(int)ceil($count/30)),(int)($_GET['p']??1)));?><section class="panel commerce-block"><form method="get" class="filter-bar"><input type="hidden" name="page" value="finance"><label>Mois<input type="month" name="month" value="<?=e($month)?>" required></label><label>Compte<select name="account"><option value="0">Tous, y compris non affectés</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=$accountFilter===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach?></select></label><button class="btn secondary">Afficher</button></form><div class="finance-summary padded"><div><span>Encaissements clients · sélection</span><strong><?=e(money(decimalString($receipts,2)))?></strong></div><div><span>Charges payées · sélection</span><strong><?=e(money(decimalString($paidExpenses,2)))?></strong></div><div><span>Flux clients − charges · hors ouvertures/transferts</span><strong><?=e(signedMoney($receipts-$paidExpenses))?></strong></div></div><div class="table-scroll"><table><thead><tr><th>DATE / SOURCE</th><th>COMPTE</th><th>DÉTAIL</th><th class="numeric">ENTRÉE</th><th class="numeric">SORTIE</th></tr></thead><tbody><?php foreach(array_slice($entries,($p-1)*30,30) as $r):?><tr><td><?=e($r['date'])?><small class="subline"><?=e($r['source'].' · '.$r['ref'])?></small></td><td><?=e($snapshot['names'][$r['account_id']]??'Non affecté')?></td><td><?=e($r['description'])?></td><td class="numeric"><?=$r['signed']>=0?e(money(decimalString($r['signed'],2))):'—'?></td><td class="numeric"><?=$r['signed']<0?e(money(decimalString(-$r['signed'],2))):'—'?></td></tr><?php endforeach?></tbody></table></div><div class="pagination"><span><?=$count?> mouvements · page <?=$p?> / <?=max(1,(int)ceil($count/30))?></span><div><?php if($p>1):?><a class="btn secondary" href="<?=e(url('finance',['month'=>$month,'account'=>$accountFilter,'p'=>$p-1]))?>">← Précédent</a><?php endif?><?php if($p*30<$count):?><a class="btn secondary" href="<?=e(url('finance',['month'=>$month,'account'=>$accountFilter,'p'=>$p+1]))?>">Suivant →</a><?php endif?></div></div></section>
<?php else:
heading('DÉPENSES DE L’ATELIER','Les charges, sans oubli.','Prévue ou payée, avec catégorie, bénéficiaire, date et compte de paiement.');
?><div class="document-actions"><a class="btn secondary" href="<?=e(url('finance'))?>">← Caisse & banque</a></div><section class="panel padded"><h2>Ajouter une charge</h2><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="expense_add"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-grid"><?php inputField('Libellé','title',$_POST['title']??'','text',true,'maxlength="190"');selectField('Catégorie','category',EXPENSE_CATEGORIES,$_POST['category']??'Autre');inputField('Bénéficiaire / fournisseur','payee',$_POST['payee']??'','text',false,'maxlength="190"');inputField('Date de charge / échéance','expense_date',$_POST['expense_date']??date('Y-m-d'),'date',true);inputField('Montant TTC · DH','amount',$_POST['amount']??'','number',true,'min="0.01" max="999999999.99" step="0.01"');selectField('Méthode','method',PAYMENT_METHODS,$_POST['method']??'Espèces');selectField('État','state',['Prévue','Payée'],$_POST['state']??'Prévue');accountSelect('account_id','Compte · obligatoire si payée',$accounts,false,isset($_POST['account_id'])?(int)$_POST['account_id']:null);inputField('Date effective du paiement · si payée','paid_date',$_POST['paid_date']??date('Y-m-d'),'date',false,'max="'.date('Y-m-d').'"');?><label>Note / référence du justificatif<textarea name="note" maxlength="1500" rows="2"><?=e($_POST['note']??'')?></textarea></label></div><p class="small muted">Un chèque reste prévu jusqu’au débit constaté. Un bulletin de paie, un achat de stock ou une intervention machine ne crée pas automatiquement une charge. Saisissez la dépense une seule fois.</p><button class="btn primary">Enregistrer la charge</button></form></section>
<?php $state=in_array($_GET['state']??'',['Prévue','Payée','Annulée'],true)?$_GET['state']:'';$args=$state?[$state]:[];$where=$state?'WHERE x.state=?':'';$count=(int)scalar('SELECT COUNT(*) FROM finance_expenses x '.$where,$args);$p=max(1,min(max(1,(int)ceil($count/20)),(int)($_GET['p']??1)));$expenses=all('SELECT x.*,a.name account_name FROM finance_expenses x LEFT JOIN finance_accounts a ON a.id=x.account_id '.$where.' ORDER BY x.id DESC LIMIT 20 OFFSET '.(($p-1)*20),$args);?><section class="panel commerce-block"><form method="get" class="filter-bar"><input type="hidden" name="page" value="expenses"><label>État<select name="state"><option value="">Toutes les charges</option><?php foreach(['Prévue','Payée','Annulée'] as $st):?><option <?=$state===$st?'selected':''?>><?=e($st)?></option><?php endforeach?></select></label><button class="btn secondary">Filtrer</button></form><div class="table-scroll"><table><thead><tr><th>CHARGE</th><th>DATES</th><th>ÉTAT / COMPTE</th><th class="numeric">TTC</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($expenses as $x):?><tr><td><strong><?=e($x['title'])?></strong><small class="subline">CHG-<?=(int)$x['id']?> · <?=e($x['category'])?></small><small class="subline"><?=e($x['payee'])?></small><small class="subline"><?=e($x['note'])?></small></td><td><?=e($x['expense_date'])?><small class="subline">Payée : <?=e($x['paid_date']?:'—')?></small></td><td><?=e($x['state'])?><small class="subline"><?=e($x['account_name']?:'Non affecté')?> · <?=e($x['method'])?></small><?php if($x['state']==='Annulée'):?><small class="subline"><?=e($x['cancel_reason'])?></small><?php endif?></td><td class="numeric"><?=e(money($x['amount']))?></td><td><?php if($x['state']==='Prévue'):?><details><summary>Constater le paiement</summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="expense_paid"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><?php accountSelect('account_id','Compte débité',$accounts,true);inputField('Date effective','paid_date',date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"');?><button class="btn secondary">Confirmer le débit</button></form></details><?php endif?><?php if($x['state']!=='Annulée'):?><details><summary>Annuler la saisie</summary><form method="post" data-confirm="Annuler cette saisie erronée et retirer son effet des soldes ? Aucun remboursement n’est effectué."><?=csrf()?><input type="hidden" name="action" value="expense_cancel"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><?php inputField('Motif de correction','cancel_reason','','text',true,'maxlength="1000"');?><button class="btn secondary">Annuler la saisie erronée</button></form></details><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php pagination($count,$p,'expenses',['state'=>$state]);?></section><?php endif?>
